SourceCode.Declaration:
/// <summary>
/// Shows the environment data setup group in the personalization pop-up only for controls bound to a data source,
/// and only to users who can maintain the data setup.
/// </summary>
[ExtensionOf(formStr(FormControlQuickPersonalization))]
final class FormControlQuickPersonalization_Form_OLK_Eds_Extension
{
}

Method.Source:
public void loadControlsState()
{
    next loadControlsState();

    FormControl personalizedControl = this.args() ? this.args().parmObject() : null;
    FormControl edsGroup = this.design().controlName(formControlStr(FormControlQuickPersonalization, OLK_EnvironmentDataSetupGroup));

    if (edsGroup)
    {
        edsGroup.visible(personalizedControl
            && personalizedControl.dataSourceObject()
            && isConfigurationkeyEnabled(configurationKeyNum(OLK_EdsConfigKey))
            && hasMenuItemAccess(menuItemDisplayStr(OLK_EnvironmentDataSetupTrans), MenuItemType::Display));
    }
}
